"use client"

import * as React from "react"

import { useComposedRefs } from "@/lib/0nlytype/refs"
import { cn } from "@/lib/utils"

type SelectProps = React.ComponentProps<"select"> & {
  /** The words before the choice: "Sort by". Clicking them opens the list. */
  label?: React.ReactNode
  /**
   * underline (default): the chosen word, italic over a hairline.
   * compose: a new choice is set from the letters of the last; the ones they share slide over.
   * ruby: the other choices are set small above the word; point at one to pick it.
   */
  variant?: "underline" | "compose" | "ruby"
  /** Classes for the sentence around the choice. className goes to the select. */
  rootClassName?: string
  /** Pins a state for documentation ("hover"); set on the root. */
  "data-force"?: string
}

type Choice = { value: string; label: string }

const text = (node: React.ReactNode): string =>
  typeof node === "string" || typeof node === "number" ? String(node) : Array.isArray(node) ? node.map(text).join("") : ""

/** The <option>s among the children, for the first paint. After that the select itself is read. */
function choicesOf(children: React.ReactNode): Choice[] {
  return React.Children.toArray(children).flatMap((child) => {
    if (!React.isValidElement<React.ComponentProps<"option">>(child) || child.type !== "option") return []
    const label = text(child.props.children)
    return [{ value: child.props.value === undefined ? label : String(child.props.value), label }]
  })
}

const read = (el: HTMLSelectElement): Choice[] => Array.from(el.options, (o) => ({ value: o.value, label: o.text }))
const graphemes = (s: string) => Array.from(new Intl.Segmenter(undefined, { granularity: "grapheme" }).segment(s), (g) => g.segment)
/** Distance from the word's inline start to a letter's inline start, so right to left measures the same way. */
function edge(word: HTMLElement) {
  const rtl = getComputedStyle(word).direction === "rtl"
  const box = word.getBoundingClientRect()
  const at = (el: Element) => {
    const r = el.getBoundingClientRect()
    return rtl ? box.right - r.right : r.left - box.left
  }
  return Object.assign(at, { dir: rtl ? -1 : 1 })
}
/** A tempo token in milliseconds: the tokens are written in seconds or milliseconds. */
const ms = (v: string, fallback: number) => (v.trim().endsWith("ms") ? parseFloat(v) : parseFloat(v) * 1000) || fallback
const still = () => typeof matchMedia === "undefined" || matchMedia("(prefers-reduced-motion: reduce)").matches

/** A choice inside a sentence. The chosen word is yours, in italic over a hairline. Give it <option>s. */
function Select({ label, variant = "underline", className, rootClassName, "data-force": force, children, onChange, ref: forwardedRef, ...props }: SelectProps) {
  const Root = label ? "label" : "span"
  const drawn = variant !== "underline"
  const select = React.useRef<HTMLSelectElement>(null)
  const composedRef = useComposedRefs(select, forwardedRef)
  const box = React.useRef<HTMLSpanElement>(null)
  const word = React.useRef<HTMLSpanElement>(null)
  const ghosts = React.useRef<HTMLSpanElement>(null)
  const ruby = React.useRef<HTMLSpanElement>(null)
  // Where things stood the moment before a change, so the layout effect can move them from there.
  const before = React.useRef<{ width: number; sorts: { ch: string; x: number }[]; line?: DOMRect; picked?: DOMRect; tier: Map<string, number>; was: string } | null>(null)

  const [choices, setChoices] = React.useState<Choice[]>(() => choicesOf(children))
  const [current, setCurrent] = React.useState<string>(() => {
    const want = props.value ?? props.defaultValue
    return want === undefined ? (choicesOf(children)[0]?.value ?? "") : String(want)
  })

  // The select is the truth: read it after mount, and whenever a controlled value or the options change.
  React.useLayoutEffect(() => {
    if (!drawn || !select.current) return
    setChoices(read(select.current))
    setCurrent(select.current.value)
  }, [drawn, props.value, children])

  const chosen = choices.find((c) => c.value === current)?.label ?? ""

  React.useLayoutEffect(() => {
    const from = before.current
    before.current = null
    if (!from || !box.current || !word.current || still()) return
    const css = getComputedStyle(box.current)
    const moderato = ms(css.getPropertyValue("--ot-moderato"), 320)
    const allegro = ms(css.getPropertyValue("--ot-allegro"), 160)
    const breath = css.getPropertyValue("--ot-breath").trim() || "ease"
    const spiccato = css.getPropertyValue("--ot-spiccato").trim() || "ease-out"
    const width = box.current.offsetWidth
    if (width !== from.width) box.current.animate([{ width: `${from.width}px` }, { width: `${width}px` }], { duration: moderato, easing: breath })

    if (variant === "compose") {
      // The compositor's stick: every sort the two words share slides to its new place (the nearest
      // one of the same letter), the ones the new word doesn't need drop out, and the rest are set in.
      const at = edge(word.current)
      const used = new Set<number>()
      Array.from(word.current.children as HTMLCollectionOf<HTMLElement>).forEach((sort) => {
        const x = at(sort)
        const ch = (sort.textContent ?? "").toLocaleLowerCase()
        let best = -1
        from.sorts.forEach((s, j) => {
          if (!used.has(j) && s.ch.toLocaleLowerCase() === ch && ch.trim() && (best < 0 || Math.abs(s.x - x) < Math.abs(from.sorts[best].x - x))) best = j
        })
        if (best >= 0) {
          used.add(best)
          sort.animate([{ translate: `${(from.sorts[best].x - x) * at.dir}px 0` }, { translate: "0 0" }], { duration: moderato, easing: breath })
        } else {
          sort.animate([{ opacity: 0, translate: "0 -0.5em" }, { opacity: 1, translate: "0 0" }], { duration: moderato, delay: allegro / 2, easing: spiccato, fill: "backwards" })
        }
      })
      from.sorts.forEach((s, j) => {
        if (used.has(j) || !ghosts.current) return
        const ghost = document.createElement("span")
        ghost.textContent = s.ch
        ghost.style[at.dir > 0 ? "left" : "right"] = `${s.x}px` // physical: the ghosts' box takes the page's direction, the word its own
        ghosts.current.append(ghost)
        ghost.animate([{ opacity: 1 }, { opacity: 0, translate: "0 0.5em" }], { duration: allegro * 1.5, easing: breath, fill: "forwards" }).finished.then(
          () => ghost.remove(),
          () => ghost.remove(),
        )
      })
    }

    if (variant === "ruby" && from.line) {
      // Interlinear: the picked word comes down out of the ruby onto the line, and the old one goes up into its place.
      // Each word travels between the two tiers and inks in as it arrives; neither is scaled, so neither is ever set in the other's face.
      const move = (el: Element | null | undefined, start?: DOMRect) => {
        if (!el || !start) return
        const end = el.getBoundingClientRect()
        const dx = getComputedStyle(el).direction === "rtl" ? start.right - end.right : start.left - end.left
        el.animate([{ translate: `${dx}px ${start.bottom - end.bottom}px`, opacity: 0 }, { translate: "0 0", opacity: 1 }], { duration: moderato, easing: breath })
      }
      // The words that stay in the ruby close up (or open) round the change.
      Array.from(ruby.current?.children ?? [], (el) => {
        const left = from.tier.get((el as HTMLElement).dataset.value ?? "")
        const dx = left === undefined ? 0 : left - el.getBoundingClientRect().left
        if (Math.abs(dx) > 0.5) el.animate([{ translate: `${dx}px 0` }, { translate: "0 0" }], { duration: moderato, easing: breath })
      })
      move(word.current, from.picked)
      move(ruby.current?.querySelector(`[data-value="${CSS.escape(from.was)}"]`), from.line)
    }
  }, [current, variant])

  const change = (e: React.ChangeEvent<HTMLSelectElement>) => {
    onChange?.(e)
    if (!drawn) return
    const next = e.currentTarget.value
    if (box.current && word.current) {
      const at = edge(word.current)
      before.current = {
        width: box.current.offsetWidth,
        sorts: Array.from(word.current.children, (s) => ({ ch: s.textContent ?? "", x: at(s) })),
        line: word.current.getBoundingClientRect(),
        picked: ruby.current?.querySelector(`[data-value="${CSS.escape(next)}"]`)?.getBoundingClientRect(),
        tier: new Map(Array.from(ruby.current?.children ?? [], (el) => [(el as HTMLElement).dataset.value ?? "", el.getBoundingClientRect().left])),
        was: current,
      }
    }
    setCurrent(next)
  }

  const pick = (value: string) => {
    const el = select.current
    if (!el || el.disabled) return
    el.value = value
    el.dispatchEvent(new Event("change", { bubbles: true }))
    el.focus({ preventScroll: true, focusVisible: false } as FocusOptions)
  }

  return (
    <Root data-slot="select" data-variant={drawn ? variant : undefined} data-force={force} className={cn("ot-select", rootClassName)}>
      {label ? <span>{label}</span> : null}
      <span ref={box} className="ot-select-box">
        <select ref={composedRef} data-slot="select-input" className={className} onChange={change} {...props}>
          {children}
        </select>
        {drawn ? (
          <span ref={word} className="ot-select-word" dir="auto" aria-hidden="true">
            {variant === "compose" ? graphemes(chosen).map((g, i) => <span key={i}>{g}</span>) : chosen}
          </span>
        ) : null}
        {variant === "compose" ? <span ref={ghosts} className="ot-select-ghosts" aria-hidden="true" /> : null}
        {variant === "ruby" ? (
          // A shortcut for the pointer only: the select below holds the same choices for the keyboard and screen readers.
          <span ref={ruby} className="ot-select-ruby" aria-hidden="true">
            {choices
              .filter((c) => c.value !== current)
              .map((c) => (
                <span
                  key={c.value}
                  data-value={c.value}
                  onClick={(e) => {
                    e.preventDefault()
                    pick(c.value)
                  }}
                >
                  {c.label}
                </span>
              ))}
          </span>
        ) : null}
      </span>
    </Root>
  )
}

export { Select, type SelectProps }

@layer components {
  /* ── ot-select ── a choice inside a sentence */
  .ot-select { display: inline-flex; flex-wrap: wrap; align-items: baseline; column-gap: 0.25em; font-size: var(--ot-mp); line-height: var(--ot-mp-lh); color: var(--ot-graphite); }
  .ot-select-box { position: relative; display: inline-flex; align-items: baseline; }
  .ot-select-box::after {
    content: "↓" / ""; position: absolute; inset-inline-end: 0; bottom: 0.3em;
    font-family: var(--ot-voice); font-size: 0.72em; line-height: 1; color: var(--ot-pencil); pointer-events: none;
    transition: translate var(--ot-moderato) var(--ot-exhale), color var(--ot-allegro);
  }
  :is(.ot-select-box:hover, .ot-select[data-force~="hover"] .ot-select-box)::after { translate: 0 2px; color: var(--ot-ink); }
  .ot-select select {
    -webkit-appearance: none; appearance: none; field-sizing: content;
    margin: 0; border: 0; border-radius: 0; padding: 0 0.6em 0.1em 0; /* the arrow sits in the padding */
    background: linear-gradient(var(--ot-rule-strong), var(--ot-rule-strong)) no-repeat 0 100% / calc(100% - 0.6em) var(--ot-hairline);
    color: var(--ot-ink); cursor: pointer;
    font-family: var(--ot-expression); font-style: italic; font-weight: 400;
    font-size: calc(var(--ot-expression-scale) * 1em); line-height: 1.2;
  }
  .ot-select select:is([dir="rtl"], [dir="rtl"] *) { padding: 0 0 0.1em 0.6em; background-position: 100% 100%; }
  .ot-select select:focus-visible { outline-offset: 4px; }
  .ot-select select:disabled { color: var(--ot-pencil); cursor: not-allowed; }
  @supports (appearance: base-select) {
    .ot-select select, .ot-select select::picker(select) { appearance: base-select; }
    .ot-select select { display: inline-flex; min-block-size: 0; }
    .ot-select select::picker-icon { display: none; }
    .ot-select select::picker(select) {
      margin-top: var(--ot-space-2); padding: var(--ot-space-2) 0; border: 0;
      background: var(--ot-paper); box-shadow: inset 0 0 0 var(--ot-hairline) var(--ot-rule);
      color: var(--ot-graphite); scrollbar-width: none; /* the picker is the browser's own: it takes no rail, and only a very long list scrolls */
    }
    .ot-select option { padding: 0.3em 1.1em; }
    .ot-select option::checkmark { display: none; }
    .ot-select option { position: relative; padding-inline-start: 1.6em; }
    .ot-select option:checked { color: var(--ot-ink); }
    .ot-select option:checked::before { content: ""; position: absolute; inset-inline-start: 0.7em; top: calc(50% - 3px); width: 6px; height: 6px; border-radius: 50%; background: var(--ot-accent); }
    .ot-select option:is(:hover, :focus-visible) { background: var(--ot-mark); color: var(--ot-on-mark); outline: 0; }
    .ot-select select::picker(select) { transition: opacity var(--ot-moderato) var(--ot-exhale), translate var(--ot-moderato) var(--ot-exhale), overlay var(--ot-moderato) allow-discrete, display var(--ot-moderato) allow-discrete; }
    @starting-style { .ot-select select:open::picker(select) { opacity: 0; translate: 0 -6px; } }
    .ot-select select:open option { animation: ot-arrive var(--ot-moderato) var(--ot-exhale) backwards; animation-delay: calc((sibling-index() - 1) * var(--ot-arpeggio)); }
  }

  /* ── The drawn variants: the select keeps the focus, the keyboard and the list, but its own words
     are made invisible and a copy is set in the same place that script can move. The hairline moves
     to the box, so it can stretch between the old word's width and the new one's. */
  .ot-select[data-variant] .ot-select-box { display: inline-grid; background: linear-gradient(var(--ot-rule-strong), var(--ot-rule-strong)) no-repeat 0 100% / calc(100% - 0.6em) var(--ot-hairline); }
  .ot-select[data-variant] .ot-select-box:is([dir="rtl"], [dir="rtl"] *) { background-position: 100% 100%; }
  .ot-select[data-variant] .ot-select-box > * { grid-area: 1 / 1; }
  .ot-select[data-variant] select { color: transparent; background: none; }
  .ot-select[data-variant] option { color: var(--ot-ink); } /* a native list would take the select's colour */
  .ot-select-word, .ot-select-ghosts {
    padding: 0 0.6em 0.1em 0; white-space: pre; pointer-events: none; color: var(--ot-ink);
    font-family: var(--ot-expression); font-style: italic; font-weight: 400; font-size: calc(var(--ot-expression-scale) * 1em); line-height: 1.2;
  }
  .ot-select-word:is([dir="rtl"], [dir="rtl"] *) { padding: 0 0 0.1em 0.6em; }
  .ot-select-word > span { display: inline-block; }
  .ot-select-ghosts { position: relative; }
  .ot-select-ghosts > span { position: absolute; top: 0; color: var(--ot-pencil); }
  .ot-select:has(select:disabled) :is(.ot-select-word, .ot-select-ruby) { color: var(--ot-pencil); pointer-events: none; }
  .ot-select[data-variant] select:disabled + .ot-select-word { cursor: not-allowed; }

  /* ruby: the other choices set small above the word, as ruby rides over a line of Japanese.
     Ours (roman, pencil) over yours (italic, ink). They hang from the word's start and may overhang
     the words after it, so the sentence gives them a line of their own above. */
  .ot-select[data-variant="ruby"] .ot-select-box { margin-block-start: calc(var(--ot-pp) * var(--ot-pp-lh)); }
  .ot-select-ruby {
    position: absolute; inset-inline-start: 0; bottom: 100%; display: flex; gap: 0 0.9em; white-space: nowrap;
    font-family: var(--ot-voice); font-style: normal; font-size: var(--ot-pp); line-height: var(--ot-pp-lh); color: var(--ot-pencil);
  }
  .ot-select-ruby > span {
    padding-block: 0.3em 0.15em; cursor: pointer;
    background: linear-gradient(currentColor, currentColor) no-repeat 0 100% / 0% var(--ot-hairline);
    transition: color var(--ot-allegro), background-size var(--ot-moderato) var(--ot-exhale);
  }
  .ot-select-ruby > span:is([dir="rtl"], [dir="rtl"] *) { background-position: 100% 100%; }
  .ot-select-ruby > span:hover, .ot-select[data-force~="hover"] .ot-select-ruby > span:first-child { color: var(--ot-ink); background-size: 100% var(--ot-hairline); }

  @media (forced-colors: active) {
    .ot-select[data-variant] select { color: CanvasText; }
    .ot-select-word, .ot-select-ghosts { display: none; }
    .ot-select-ruby > span:hover { color: LinkText; }
  }
}
